package validation_record

import "context"

// Repository is the persistence seam for the validation_record domain.
//
// seam: Repository
type Repository interface {
	// Append inserts a new record. The ID is server-generated by the
	// service before this is called.
	Append(ctx context.Context, r Record) error

	// Get returns one record by id.
	Get(ctx context.Context, id string) (Record, error)

	// List returns up to pageSize records matching the filter,
	// ordered by ended_at descending (most recent first). pageToken
	// is the opaque cursor returned by the previous call; pass "" for
	// the first page. NextPageToken is empty when no more pages exist.
	List(ctx context.Context, f ListFilter, pageSize int, pageToken string) (ListResult, error)
}
